---@class SPayActivityPkHandler : SPacketHandlers
local PayActivityPkHandler = T(Global, "PacketHandlers")
---@type PayActivityRewardConfig
local PayActivityRewardConfig = T(Global, "PayActivityRewardConfig")

function PayActivityPkHandler:runPayActivityFunc(packet)
    local activity = self.payActivity.activities[packet.activityId]
    if not activity then
        return
    end
    if not activity:isC2SFuncRegister(packet.name) then
        return
    end
    activity:runServerFunc(packet.name, table.unpack(packet.params))
end

function PayActivityPkHandler:requestCheckPlayerHasRewardItem(packet)
    --print("PayActivityPkHandler:requestCheckPlayerHasRewardItem",self.userId)
    --LogUtil.pv(packet)
    if self.checkHasRewardItem and packet.rewardIdList then
        local rewardList={}
        for _, v in pairs(packet.rewardIdList) do
            local reward=PayActivityRewardConfig:getCfgById(v)
            if reward then
                table.insert(rewardList,reward)
            end
        end
        local hasRewardInf=self:checkHasRewardItem(rewardList)
        local activity = self.payActivity.activities[packet.activityId]
        if  activity then
            activity.hasRewardInf=TableUtil.copyTable(hasRewardInf)
        end
        return hasRewardInf
    end
    return {}
end

return PayActivityPkHandler